// Get current time
const now = new Date();
const currentHour = now.getHours();
const currentMinute = now.getMinutes();

// Target: 21:00
const targetHour = 21;
const targetMinute = 0;

// Calculate next occurrence
let alarmDate = new Date();
alarmDate.setHours(targetHour, targetMinute, 0, 0);

// If it's already past 21:00 today, schedule for tomorrow
if (currentHour > targetHour || (currentHour === targetHour && currentMinute >= targetMinute)) {
    alarmDate.setDate(alarmDate.getDate() + 1);
}

// Build alarm payload
msg.payload = {
    device_id: env.get("VELYA_DEVICE_ID") || "YOUR_DEVICE_ID_HERE",
    hour: targetHour,
    minute: targetMinute,
    enabled: true,
    label: "Automated 21h Alarm",
    sound: "radar",
    snooze_enabled: true,
    vibrate: true,
    days_of_week: [1, 2, 3, 4, 5, 6, 7], // Every day
    webhook_url: `${env.get("VELYA_WEBHOOK_BASE")}/velya-webhook` || "http://localhost:1880/velya-webhook"
};

// Store alarm time for debugging
msg.alarmTime = alarmDate.toISOString();
msg.alarmHuman = alarmDate.toLocaleString('fr-FR', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
});

node.status({
    fill: "blue",
    shape: "dot",
    text: `Next: ${msg.alarmHuman}`
});

return msg;

node.status({
    fill: "green",
    shape: "dot",
    text: `Alarm created: ${msg.payload.alarm_id}`
});

// Store alarm ID for tracking
flow.set(`velya_last_alarm_id`, msg.payload.alarm_id);
flow.set(`velya_last_alarm_time`, new Date().toISOString());

msg.success = true;
msg.alarm_id = msg.payload.alarm_id;

return msg;

const error = msg.payload.error || msg.statusCode || "Unknown error";

node.status({
    fill: "red",
    shape: "ring",
    text: `Failed: ${error}`
});

node.error(`Velya alarm creation failed: ${JSON.stringify(msg.payload)}`, msg);

msg.error = error;
msg.success = false;

// Store failure for retry logic
flow.set(`velya_last_error`, {
    time: new Date().toISOString(),
    error: error,
    payload: msg.payload
});

return msg;

// Get current retry count
const retries = flow.get(`velya_retry_count`) || 0;
const maxRetries = 3;

if (retries < maxRetries) {
    flow.set(`velya_retry_count`, retries + 1);
    node.status({
        fill: "yellow",
        shape: "ring",
        text: `Retry ${retries + 1}/${maxRetries}`
    });
    return msg; // Retry
} else {
    flow.set(`velya_retry_count`, 0);
    node.status({
        fill: "red",
        shape: "dot",
        text: `Failed after ${maxRetries} retries`
    });
    node.error(`Velya alarm failed after ${maxRetries} retries`, msg);
    return null; // Stop retrying
}

// Velya sends:
// {
//   "event": "alarm.delivered",
//   "alarm_id": "uuid",
//   "device_id": "uuid",
//   "delivered_at": "2024-05-28T21:00:03.123Z",
//   "delivery_method": "websocket" | "apns"
// }

const payload = msg.payload;

if (payload.event === "alarm.delivered") {
    node.status({
        fill: "green",
        shape: "dot",
        text: `Delivered via ${payload.delivery_method}`
    });

    // Store delivery confirmation
    flow.set(`velya_last_delivery`, {
        alarm_id: payload.alarm_id,
        time: payload.delivered_at,
        method: payload.delivery_method
    });

    msg.statusCode = 200;
    msg.payload = { success: true };
} else {
    node.warn(`Unknown webhook event: ${payload.event}`);
    msg.statusCode = 400;
    msg.payload = { error: "Unknown event" };
}

return msg;
